using System.Security.Cryptography;
using DiscForge.Core.Chd;
using Xunit;

namespace DiscForge.Core.Tests;

/// <summary>
/// CHD cdlz (LZMA) extraction, validated against a real chdman all-LZMA image of
/// the same track as the cdzl test. The raw LZMA decoder + hunk walk must self-
/// verify against the CHD's stored SHA-1 and reproduce the identical track bytes,
/// proving the LZMA path independently of the zlib one.
/// </summary>
public class ChdLzmaTests
{
    private static byte[] Sample() => System.Convert.FromBase64String(Cdlz);

    [Fact]
    public void RealCdlzChd_ExtractsVerifiedAndByteExact()
    {
        var r = ChdExtractor.ExtractCd(Sample());
        Assert.True(r.Verified);
        Assert.Equal(1, r.Tracks);
        Assert.Equal(2822400, r.Bin.Length);
        string sha = System.Convert.ToHexString(SHA256.HashData(r.Bin)).ToLowerInvariant();
        Assert.Equal("ba42d5132f62d7f39fe8ce186f32e71de3c06653154905fc0123052abde59ebd", sha);
    }

    [Fact]
    public void Codec_is_cdlz()
    {
        Assert.Equal("cdlz", ChdReader.Read(Sample()).Compressors[0]);
    }

